CREATE TABLE public.regions (code varchar(6) PRIMARY KEY, name varchar(64) NOT NULL, level smallint NOT NULL CHECK (level IN (1,2,3)), parent_code varchar(6) REFERENCES public.regions(code), path varchar(20) NOT NULL UNIQUE, status smallint NOT NULL DEFAULT 1 CHECK (status IN (0,1)), CONSTRAINT regions_code_check CHECK (code ~ '^[0-9]{6}$'), CONSTRAINT regions_parent_check CHECK ((level = 1 AND parent_code IS NULL AND path = code) OR (level = 2 AND parent_code IS NOT NULL AND path = parent_code || '.' || code) OR (level = 3 AND parent_code IS NOT NULL AND path ~ ('^[0-9]{6}\.' || parent_code || '\.' || code || '$'))));
